/* head 是链表头；节点类型由平台提供，空指针表示空链表。 */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
struct ListNode  {
    int val;
    struct ListNode*next;
}
;
struct ListNode* reverseList(struct ListNode*head) {
    struct ListNode*prev=NULL;
    while(head) {
        struct ListNode*next=head->next;
        head->next=prev;
        prev=head;
        head=next;
    }
    return prev;
}
int main(void) {
    int n;
    scanf("%d",&n);
    struct ListNode *nodes=calloc(n?n:1,sizeof(*nodes));
    for(int i=0; i<n; i++) {
        scanf("%d",&nodes[i].val);
        nodes[i].next=i+1<n?&nodes[i+1]:NULL;
    }
    struct ListNode*p=reverseList(n?nodes:NULL);
    int k=0;
    /* 先保存原 next，再让当前节点连接已反转前缀，否则会丢失剩余链。 */
    while(p&&k<n) {
        if(k)
        /* prev 指向全部已处理节点的反序，循环结束后它就是新表头。 */
        printf(" ");
        printf("%d",p->val);
        p=p->next;
        k++;
    }
    if(p||k!=n)return 3;
    printf("\n");
    free(nodes);
    return 0;
}

