/* head 是链表头；节点类型由平台提供，空指针表示空链表。 */
import java.util.*;
class ListNode  {
    int val;
    ListNode next;
    ListNode(int x) {
        val=x;
    }
}
class Solution  {
    public ListNode reverseList(ListNode head) {
        ListNode prev=null;
        while(head!=null) {
            ListNode next=head.next;
            head.next=prev;
            prev=head;
            head=next;
        }
        return prev;
    }
}
public class Main  {
    static class Fast  {
        private final byte[] b=new byte[65536];
        int p=0,n=0;
        int read()throws Exception {
            if(p>=n) {
                n=System.in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next()throws Exception {
            StringBuilder s=new StringBuilder();
            int c;
            do {
                c=read();
            }
            while(c<=32&&c>=0);
            while(c>32) {
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        int num()throws Exception {
            return Integer.parseInt(next());
        }
    }
    public static void main(String[]args)throws Exception {
        Fast f=new Fast();
        int n=f.num();
        ListNode head=null,tail=null;
        for(int i=0; i<n; i++) {
            ListNode p=new ListNode(f.num());
            if(tail==null)head=p;
            else tail.next=p;
            tail=p;
        }
        ListNode p=new Solution().reverseList(head);
        StringBuilder out=new StringBuilder();
        int k=0;
        /* 先保存原 next，再让当前节点连接已反转前缀，否则会丢失剩余链。 */
        while(p!=null&&k<n) {
            if(k>0)out.append(" ");
            out.append(p.val);
            p=p.next;
            k++;
        }
        if(p!=null||k!=n)throw new IllegalStateException("invalid list length/cycle");
        System.out.
        /* prev 指向全部已处理节点的反序，循环结束后它就是新表头。 */
        println(out);
    }
}

