import sys
class ListNode:
    def __init__(self,val=0,next=None):self.val,self.next=val,next

class Solution:
    def reverseList(self,head):
        prev=None
        # 先保存原 next，再让当前节点连接已反转前缀，否则会丢失剩余链。
        while head:
            nxt=head.next
            head.next=prev
            prev,head=head,nxt
        # prev 指向全部已处理节点的反序，循环结束后它就是新表头。
        return prev

data=sys.stdin.buffer.read().split()
n=int(data[0]);head=None
for v in reversed(data[1:]):head=ListNode(int(v),head)
p=Solution().reverseList(head);out=[]
while p is not None and len(out)<n:
    out.append(str(p.val));p=p.next
