/* head 是链表头；节点类型由平台提供，空指针表示空链表。 */
use std::io:: {
    self, Read
}
;
use std::collections::HashMap;
struct Solution;
#[derive(Debug)]
pub struct ListNode  {
    pub val:i32,pub next:Option<Box<ListNode>>
}
impl Solution  {
    pub fn reverse_list(mut head:Option<Box<ListNode>>)->Option<Box<ListNode>> {
        let mut prev=None;
        while let Some(mut node)=head {
            head=node.next.take();
            node.next=prev;
            prev=Some(node);
        }
        prev
    }
}
fn main() {
    let mut s=String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut it=s.split_whitespace();
    let n:usize=it.next().unwrap().parse().unwrap();
    let vals:Vec<i32>=(0..n).map(|_|it.next().unwrap().parse().unwrap()).collect();
    let mut head=None;
    for &v in vals.iter().rev() {
        head=Some(Box::new(ListNode {
            val:v,next:head
        }
        ));
    }
    let mut p=Solution::reverse_list(head);
    let mut out=Vec::new();
    /* 先保存原 next，再让当前节点连接已反转前缀，否则会丢失剩余链。 */
    while let Some(mut node)=p {
        assert!(out.len()<n,"invalid list length");
        out.push(node.val.to_string());
        p=node.next.take();
    }
    assert_eq!(out.len(),n);
    /* prev 指向全部已处理节点的反序，循环结束后它就是新表头。 */
    println!("{}",out.join(" "));
}

